import { readFileSync } from 'node:fs';
import path from 'node:path';

import type { FuegoIndex, IndexEntry } from '../../scripts/build-index';
import { demoSeries } from './demo-series';

/**
 * The series the page renders, read at build time.
 *
 * Server-only: the index is generated by the prebuild step from data/bulletins/
 * and never shipped to the client as a module.
 */

/**
 * Below this the chart has nothing to say, so fall back to the placeholder and
 * label it. Better an honest stand-in than three lonely points pretending to be
 * a record.
 */
const MIN_REAL_DAYS = 14;

export interface SeriesResult {
  series: IndexEntry[];
  /** True when the series is generated rather than collected. */
  isRepresentative: boolean;
  /** Days the parser could not fully read. */
  daysWithWarnings: number;
  firstDate: string | null;
  lastDate: string | null;
}

export function loadSeries(): SeriesResult {
  try {
    const raw = readFileSync(path.join(process.cwd(), 'data', 'index.json'), 'utf8');
    const index = JSON.parse(raw) as FuegoIndex;

    if (index.entries.length >= MIN_REAL_DAYS) {
      return {
        series: index.entries,
        isRepresentative: false,
        daysWithWarnings: index.stats.daysWithWarnings,
        firstDate: index.stats.firstDate,
        lastDate: index.stats.lastDate,
      };
    }
  } catch {
    // No archive yet — the placeholder below keeps the site buildable.
  }

  const series = demoSeries();
  return {
    series,
    isRepresentative: true,
    daysWithWarnings: 0,
    firstDate: series[0]?.date ?? null,
    lastDate: series.at(-1)?.date ?? null,
  };
}
